import { d } from '@cetusprotocol/common-sdk'
import { Box, BoxProps, Skeleton, Text, VStack } from '@chakra-ui/react'
import { useEffect, useMemo, useRef, useState } from 'react'

interface Props {
  minPrice: string
  maxPrice: string
  currPrice: string
  isActive: boolean
  wrapStyle?: BoxProps
  isShowActive?: boolean
}
export default function PositionPriceBar({ minPrice, maxPrice, currPrice, isActive, wrapStyle, isShowActive = false }: Props) {
  const elementRef = useRef<HTMLDivElement>(null)
  const [elementWidth, setElementWidth] = useState<number>(0)

  useEffect(() => {
    const updateWidths = () => {
      if (elementRef.current) setElementWidth(elementRef.current.offsetWidth)
    }
    const resizeObserver = new ResizeObserver(updateWidths)
    if (elementRef.current) resizeObserver.observe(elementRef.current)
    return () => {
      if (elementRef.current) resizeObserver.unobserve(elementRef.current)
    }
  }, [minPrice, maxPrice, currPrice])

  const sliderML = useMemo(() => {
    if (maxPrice === '∞') return '0px'
    if (currPrice && minPrice && maxPrice && elementWidth) {
      if (d(currPrice).lessThanOrEqualTo(maxPrice) && d(currPrice).greaterThanOrEqualTo(minPrice)) {
        const relative = d(currPrice).sub(minPrice).div(d(maxPrice).sub(minPrice)).toString()
        return `${d(elementWidth).mul(relative).toFixed(0)}px`
      }
      if (d(currPrice).lt(minPrice)) return '-6px'
      if (d(currPrice).gt(maxPrice)) return 'calc(100% + 6px)'
    }
    return '0px'
  }, [currPrice, minPrice, maxPrice, elementWidth])

  return (
    <VStack height="100%" justifyContent="space-between" {...wrapStyle}>
      <Skeleton h="6px" isLoaded={!!currPrice} borderRadius="4px">
        <Box w="88px" h="6px" bgImage={maxPrice === '∞' ? 'none' : "url('/images/img_inactive_bg@2x.png')"} bgSize="88px 6px" {...wrapStyle}>
          <Box
            w={maxPrice === '∞' ? '88px' : '56px'}
            h={maxPrice === '∞' ? '2px' : '6px'}
            position="relative"
            ref={elementRef}
            background={
              maxPrice === '∞' ? 'linear-gradient(135deg, #68FFD8 0%, #0091FF 100%)' : isActive ? "url('/images/img_range@2x.png')" : 'none'
            }
            ml={maxPrice === '∞' ? '0px' : '16px'}
            bgSize="100% 6px"
            bgPosition="center"
            bgRepeat="no-repeat"
          >
            {maxPrice !== '∞' && (
              <Box
                w="2px"
                h="8px"
                bg="#fff"
                borderRadius="8px"
                position="absolute"
                top="50%"
                left={sliderML}
                transform="translateY(-50%)"
                zIndex="5"
              />
            )}
          </Box>
        </Box>
      </Skeleton>
      {isShowActive && (
        <Text fontSize="12px" color={isActive ? 'primary' : 'primary_gray'} fontWeight="500">
          {isActive ? 'Active' : 'Inactive'}
        </Text>
      )}
    </VStack>
  )
}
